import 'package:flutter/material.dart';

/// 🌐 SECRETER cevirileri — hafif, kod-uretimsiz sistem.
///
/// Kullanim: `context.tr('key')` (extension asagida).
/// Anahtar bulunamazsa once Ingilizce'ye, o da yoksa anahtarin kendisine
/// duser — yani ceviri eksik olsa bile arayuz ASLA bos gorunmez.
///
/// DURUST NOT: Bu paket BASLANGIC anahtar setini icerir (dil secimi,
/// ortak butonlar, karsilama). Ekranlarin tam cevirisi sonraki
/// paketlerde ekran-ekran eklenecek. Az konusulan diller icin uretime
/// cikmadan ana dili konusan biri gozden gecirmeli.
class AppLocalizations {
  final Locale locale;
  AppLocalizations(this.locale);

  static AppLocalizations of(BuildContext context) =>
      Localizations.of<AppLocalizations>(context, AppLocalizations) ??
      AppLocalizations(const Locale('en'));

  static const LocalizationsDelegate<AppLocalizations> delegate =
      _AppLocalizationsDelegate();

  String t(String key) {
    final lang = locale.languageCode;
    return _values[lang]?[key] ?? _values['en']?[key] ?? key;
  }

  /// 🚪 KAPI TESTİ İÇİN: dil kodu → o dilde TANIMLI anahtarlar.
  ///
  /// ── NEDEN AÇILDI ──
  /// [t] eksik anahtarı sessizce İngilizce'ye düşürür. Bu iyi bir
  /// davranış (arayüz asla boş kalmaz) ama bir yan etkisi var: **eksik
  /// çeviri hiçbir yerde görünmüyordu.** `tr`+`en`'e anahtar eklemek
  /// diğer 14 dili sessizce geride bırakıyordu ve açık, kimse bakmadığı
  /// için 89 anahtara kadar büyümüştü.
  ///
  /// Bu getter yalnızca testin açığı ÖLÇEBİLMESİ için var; üretim kodu
  /// kullanmaz. Kapının kendisi `test/core/i18n/translation_gate_test.dart`.
  @visibleForTesting
  static Map<String, Set<String>> get keysByLanguage => {
        for (final e in _values.entries) e.key: e.value.keys.toSet(),
      };

  /// Kapı testi için: bir dildeki ham değerler (boş metin taraması).
  @visibleForTesting
  static Map<String, String> valuesFor(String lang) =>
      _values[lang] ?? const {};

  // ============================================================
  // ÇEVİRİ TABLOSU — her dil için { anahtar: metin }
  // Yeni ekran çevirirken: buraya anahtar ekle, ekranda context.tr('...')
  // ============================================================
