/// Kolay erisim: `context.tr('key')`
extension AppLocalizationsX on BuildContext {
  String tr(String key) => AppLocalizations.of(this).t(key);
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) =>
      AppLocalizations._values.keys.contains(locale.languageCode);

  @override
  Future<AppLocalizations> load(Locale locale) async =>
      AppLocalizations(locale);

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

/// Sunucuda saklanan medya onizlemeleri kod sabiti oldugu icin daima
/// Turkce uretilir ('🖼️ Fotograf' gibi). Bu yardimci, GORUNTULEME
/// aninda onlari secili dile cevirir — eski mesajlar dahil calisir.
extension PreviewLocalizationX on BuildContext {
  String trPreview(String raw) {
    // 📞 ÇAĞRI İŞARETİ — TAM DEĞİŞTİRME GEREKİR
    //
    // Biçim: '📞 call:<tur>:<saniye>'  (ör. '📞 call:audio:112')
    // Bu, parça değiştirmeyle çevrilemez: 'call:' → 'Arama' yapılınca
    // geriye 'audio:112' kalıyor ve "Aramaaudio:112" görünüyordu.
    // Bu yüzden işaret önce yakalanır ve METNİN TAMAMI yeniden kurulur.
    if (raw.contains('📞 call:')) {
      final i = raw.indexOf('📞 call:');
      final parts = raw.substring(i + '📞 call:'.length).split(':');
      final isVideo = parts.isNotEmpty && parts[0] == 'video';
      final sec = parts.length > 1 ? (int.tryParse(parts[1]) ?? 0) : 0;
      final m = sec ~/ 60;
      final sn = sec % 60;
      final dur =
          m == 0 ? '${sn}s' : '${m}dk ${sn.toString().padLeft(2, '0')}s';
      final label = isVideo ? tr('preview_video') : tr('call_label');
      return sec > 0 ? '📞 $label · $dur' : '📞 $label';
    }

    var out = raw;
    const map = {
      '📞 Cevapsız çağrı': 'call_missed',
      '🔒 Mesaj': 'preview_message',
      '🖼️ Fotoğraf': 'preview_photo',
      '🎤 Sesli mesaj': 'preview_voice',
      '🎥 Video': 'preview_video',
      '📊 Anket': 'preview_poll',
      '📍 Konum': 'preview_location',
      '🎬 GIF': 'preview_gif_x',
      '🎟️ Çıkartma': 'preview_sticker',
      'Çıkartma': 'preview_sticker',
      'Silinen mesaj': 'preview_deleted',
      '🔒 (gönderildi)': 'preview_message',
      '🔒 (çözülemedi)': 'preview_message',
    };
    map.forEach((trText, key) {
      if (out.contains(trText)) {
        final emoji = trText.startsWith('🔒')
            ? '🔒 '
            : trText.startsWith('🖼️')
                ? '🖼️ '
                : trText.startsWith('🎤')
                    ? '🎤 '
                    : trText.startsWith('🎥')
                        ? '🎥 '
                        : trText.startsWith('📊')
                            ? '📊 '
                            : trText.startsWith('📍')
                                ? '📍 '
                                : trText.startsWith('🎬')
                                    ? '🎬 '
                                    : '';
        final translated = key == 'preview_gif_x' ? 'GIF' : tr(key);
        out = out.replaceAll(trText, '$emoji$translated');
      }
    });
    return out;
  }
}
